package com.yuegang.zhihui.auth.infrastructure;
import com.yuegang.zhihui.auth.domain.*;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.security.*;import com.yuegang.zhihui.system.api.*;import java.time.*;import org.springframework.core.ParameterizedTypeReference;import org.springframework.web.client.RestClient;
public final class HttpSystemAuthorityProvider implements AuthorityProvider{private final RestClient client;private final InternalServiceSignature signatures;private final Clock clock;public HttpSystemAuthorityProvider(String base,byte[]secret,Clock c){client=RestClient.builder().baseUrl(base).build();signatures=new InternalServiceSignature(secret,c,Duration.ofSeconds(30));clock=c;}public Authorities find(long userId){String path="/internal/v1/authorizations/"+userId;Instant now=clock.instant();var m=new InternalServiceSignature.Metadata("ygh-auth-service","GET",path,now);ApiResponse<AuthoritySnapshot> response=client.get().uri(path).header("X-YGH-Service","ygh-auth-service").header("X-YGH-Service-Timestamp",Long.toString(now.toEpochMilli())).header("X-YGH-Service-Signature",signatures.sign(m)).retrieve().body(new ParameterizedTypeReference<>(){});if(response==null||response.data()==null)throw new IllegalStateException("system authority response unavailable");return new Authorities(response.data().roles(),response.data().permissions());}}
